INSERT IGNORE INTO user_role (user_id, role_id, created_at, created_by)
SELECT ua.id, r.role_id, NOW(), 'SYSTEM'
FROM user_account ua
JOIN role r ON r.role_type = 'TUTOR'
WHERE ua.id BETWEEN 1001 AND 2000;

INSERT IGNORE INTO tutor_account (tutor_id, introduction, experiences, title, educations, average_rating, review_count, matching_count, lesson_type, profile_status, bank_name, bank_account_number, bank_account_holder, is_birth_date_public, is_email_public, is_phone_number_public, created_at, created_by)
VALUES
(1001, '안녕하세요. 음악을 사랑하는 전문 튜터1입니다. 수강생의 눈높이에 맞춘 즐거운 1:1 레슨을 약속합니다.', '["레슨 경력 4년", "전문 연주자 활동"]', '기초부터 탄탄하게 배우는 피아노 맞춤형 1:1 레슨', '["음악대학 전공 졸업"]', 4.6, 1, 2, 'OFFLINE', 'COMPLETED', '국민은행', '110-1001-0001', '튜터1', 0, 0, 0, NOW(), 'SYSTEM'),
(1002, '안녕하세요. 음악을 사랑하는 전문 튜터2입니다. 수강생의 눈높이에 맞춘 즐거운 1:1 레슨을 약속합니다.', '["레슨 경력 5년", "전문 연주자 활동"]', '취미부터 입시까지 체계적인 바이올린 커리큘럼으로 지도합니다', '["음악대학 전공 졸업"]', 4.7, 2, 4, 'BOTH', 'COMPLETED', '우리은행', '110-1002-0001', '튜터2', 0, 0, 0, NOW(), 'SYSTEM'),
(1003, '안녕하세요. 음악을 사랑하는 전문 튜터3입니다. 수강생의 눈높이에 맞춘 즐거운 1:1 레슨을 약속합니다.', '["레슨 경력 6년", "전문 연주자 활동"]', '첼로 감성을 담아 연주하는 즐거움! 빠른 실력 향상 보장', '["음악대학 전공 졸업"]', 4.8, 3, 6, 'ONLINE', 'COMPLETED', '하나은행', '110-1003-0001', '튜터3', 0, 0, 0, NOW(), 'SYSTEM'),
(1004, '안녕하세요. 음악을 사랑하는 전문 튜터4입니다. 수강생의 눈높이에 맞춘 즐거운 1:1 레슨을 약속합니다.', '["레슨 경력 7년", "전문 연주자 활동"]', '어렵고 지루한 이론 대신 귀와 손이 먼저 반응하는 실전 기타 레슨', '["음악대학 전공 졸업"]', 4.9, 4, 8, 'OFFLINE', 'COMPLETED', '농협은행', '110-1004-0001', '튜터4', 0, 0, 0, NOW(), 'SYSTEM'),
